    sys.exit(2)

base = base.rstrip("/")
headers = {"Authorization": "Bearer " + token}

def do_get(path, params):
    url = base + path
    try:
        resp = requests.get(url, headers=headers, params=params, timeout=30)
    except Exception as e:
        print("request failed: " + str(e), file=sys.stderr)
        sys.exit(2)
    if resp.status_code != 200:
        print("bad status " + str(resp.status_code) + " for " + url, file=sys.stderr)
        sys.exit(2)
    try:
        data = json.loads(resp.text)
    except Exception as e:
        print("bad json for " + url + ": " + str(e), file=sys.stderr)
        sys.exit(2)
    return data

tree_data = do_get("/api/repo/paiement-api/tree", None)
if "files" not in tree_data or not isinstance(tree_data["files"], list):
    print("missing files in tree", file=sys.stderr)
    sys.exit(2)
all_files = tree_data["files"]
if len(all_files) == 0:
    print("empty file list", file=sys.stderr)
    sys.exit(2)

