    to_read.append(config_path)
for m in search_matches:
    if isinstance(m, dict) and "path" in m:
        p = m["path"]
        if p not in to_read and p in all_files:
            to_read.append(p)

app_py = []
for f in all_files:
    if f.startswith("app/") and f.endswith(".py") and f not in to_read:
