    for idx, line in enumerate(lines):
        try:
            txt = line if isinstance(line, str) else str(line)
        except Exception:
            print("bad line type", file=sys.stderr)
            sys.exit(2)
        m = prog.search(txt)
        if m:
            manual_hits.append({"path": fpath, "line": idx + 1, "text": txt})

expected = "Zero matches for verify=False, CERT_NONE, unverified context or disabled hostname check."

all_hits = []
seen = []
for m in search_matches:
    if isinstance(m, dict) and "path" in m and "line" in m:
        key = str(m.get("path")) + ":" + str(m.get("line"))
        if key not in seen:
